#include <iostream>
#include <vector>
using namespace std;
​
// 计算 num 是否为 n 位的阿姆斯特朗数（即水仙花数）
bool isArmstrongNumber(int num, int n, const vector<int>& powers) {
    int sum = 0, temp = num;
    while (temp > 0) {
        sum += powers[temp % 10];
        temp /= 10;
    }
​
    return sum == num;
}
​
int main() {
    int n, m;
    cin >> n >> m;
​
    if (n < 3 || n > 7) {
        cout << "-1" << endl;
        return 0;
    }
​
    // 预计算 0-9 的 n 次方（使用递推）
    vector<int> powers(10, 1);
    for (int i = 0; i < 10; ++i) {
        powers[i] = 1;
        for (int j = 0; j < n; ++j) {
           powers[i] *= i;
        }
    }
    // 确定枚举范围
    int start = 1;
    for (int i = 1; i < n; i++) start *= 10;
    int end = start * 10;
    // 按顺序存储水仙花数
    vector<int> armstrongList;
    for (int i = start; i < end; i++) {
        if (isArmstrongNumber(i, n, powers)) {
            armstrongList.push_back(i);
        }
    }
​
    if (armstrongList.empty()) {
        cout << "-1" << endl;
    } else {
        if (armstrongList.size() <= m) {
            cout << 1ll * m * armstrongList.back();  
        } else {
            cout << armstrongList[m];
        }
    }
​
    return 0;
}
