public class Main {
    // 判断 num 是否为 n 位的阿姆斯特朗数（即水仙花数）
    public static boolean isArmstrongNumber(int num, int n, int[] powers) {
        int sum = 0, temp = num;
        while (temp > 0) {
            sum += powers[temp % 10];
            temp /= 10;
        }
        return sum == num;
    }
​
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();  // n 位数
        int m = sc.nextInt();  // 取第 m 个
​
        if (n < 3 || n > 7) {
            System.out.println("-1");
            return;
        }
​
        // 预计算 0-9 的 n 次方
        int[] powers = new int[10];
        for (int i = 0; i < 10; i++) {
            powers[i] = 1;
            for (int j = 0; j < n; j++) {
                powers[i] *= i;
            }
        }
        // 确定枚举范围
        int start = 1;
        for (int i = 1; i < n; i++) start *= 10;
        int end = start * 10;
        // 按顺序存储水仙花数
        List<Integer> armstrongList = new ArrayList<>();
        for (int i = start; i < end; i++) {
            if (isArmstrongNumber(i, n, powers)) {
                armstrongList.add(i);
            }
        }
​
        if (armstrongList.isEmpty()) {
            System.out.println("-1");
        } else {
            if (armstrongList.size() <= m) {
                System.out.println((long)m * armstrongList.get(armstrongList.size() - 1));
            } else {
                System.out.println(armstrongList.get(m));
            }
        }
    }
}
