const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
let lines = [];
rl.on('line', line => {
    lines.push(line);
    if (lines.length === 2) {
        rl.close();
    }
});
​
rl.on('close', () => {
    const n = parseInt(lines[0], 10);
    const m = parseInt(lines[1], 10);
​
    if (n < 3 || n > 7) {
        console.log(-1);
        return;
    }
​
    // 预计算 0-9 的 n 次方
    const powers = [];
    for (let i = 0; i <= 9; i++) {
        let p = 1;
        for (let j = 0; j < n; j++) p *= i;
        powers[i] = p;
    }
    // 确定枚举范围
    const start = Math.pow(10, n - 1);
    const end = Math.pow(10, n);
    //按顺序存储水仙花数
    const result = [];
​
    // 判断是否为水仙花数
    function isArmstrong(num) {
        let temp = num, sum = 0;
        while (temp > 0) {
            sum += powers[temp % 10];
            temp = Math.floor(temp / 10);
        }
        return sum === num;
    }
​
    for (let i = start; i < end; i++) {
        if (isArmstrong(i)) {
            result.push(i);
        }
    }
​
    if (result.length === 0) {
        console.log(-1);
    } else {
        if (result.length <= m) {
            console.log(m * result[result.length - 1]);
        } else {
            console.log(result[m]);
        }
    }
