package main
​
import (
    "fmt"
    "math"
)
​
// 判断 num 是否为 n 位的阿姆斯特朗数（即水仙花数）
func isArmstrongNumber(num int, powers []int) bool {
    sum, temp := 0, num
    for temp > 0 {
        sum += powers[temp%10]
        temp /= 10
    }
    return sum == num
}
​
func main() {
    var n, m int
    fmt.Scan(&n, &m)
​
    if n < 3 || n > 7 {
        fmt.Println("-1")
        return
    }
​
    // 预计算 0-9 的 n 次方
    powers := make([]int, 10)
    for i := 0; i < 10; i++ {
        p := 1
        for j := 0; j < n; j++ {
            p *= i
        }
        powers[i] = p
    }
    // 确定枚举范围
    start := int(math.Pow10(n - 1))
    end := int(math.Pow10(n))
     // 按顺序存储水仙花数
    armstrongList := []int{}

    for i := start; i < end; i++ {
        if isArmstrongNumber(i, powers) {
            armstrongList = append(armstrongList, i)
        }
    }
​
    if len(armstrongList) == 0 {
        fmt.Println("-1")
    } else {
        if len(armstrongList) <= m {
            fmt.Println(m * armstrongList[len(armstrongList)-1])
        } else {
            fmt.Println(armstrongList[m])
        }
    }
}
